def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result

N = 120
k = N // 2  # Number of edges in a perfect matching
W = k * (combinations(N - 2, 2) - (k - 1))
print(W)
